import os
import sqlite3
import json
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret")
DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS products (
            name TEXT PRIMARY KEY,
            data TEXT NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()


def serialize_product(row):
    try:
        props = json.loads(row["data"])
    except (ValueError, TypeError):
        props = {}
    result = {"name": row["name"]}
    if isinstance(props, dict):
        for k, v in props.items():
            if k == "name":
                continue
            result[k] = v
    return result


@app.route("/add", methods=["POST"])
def add_product():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid input"}), 400

    name = payload.get("name")
    if not isinstance(name, str) or not name:
        return jsonify({"error": "Invalid input: name is required"}), 400

    extra = {}
    for k, v in payload.items():
        if k == "name":
            continue
        if not isinstance(k, str) or not isinstance(v, str):
            return jsonify({"error": "Invalid input: all properties must be strings"}), 400
        extra[k] = v

    db = get_db()
    try:
        db.execute(
            "INSERT INTO products (name, data) VALUES (?, ?)",
            (name, json.dumps(extra)),
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({"error": "Product already exists"}), 400

    return jsonify({"status": "created"}), 201


@app.route("/download", methods=["GET"])
def download_product():
    name = request.args.get("name")
    if not name:
        return jsonify({"error": "Invalid query: name is required"}), 400

    db = get_db()
    row = db.execute("SELECT name, data FROM products WHERE name = ?", (name,)).fetchone()
    if row is None:
        return jsonify({"error": "Product not found"}), 400

    return jsonify({"data": row["data"]}), 200


@app.route("/upload", methods=["POST"])
def upload_product():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid upload query"}), 400

    name = payload.get("name")
    data = payload.get("data")
    if not isinstance(name, str) or not name:
        return jsonify({"error": "Invalid upload query: name is required"}), 400
    if not isinstance(data, str):
        return jsonify({"error": "Invalid upload query: data is required"}), 400

    try:
        parsed = json.loads(data)
    except ValueError:
        return jsonify({"error": "Invalid upload query: data must be valid JSON"}), 400
    if not isinstance(parsed, dict):
        return jsonify({"error": "Invalid upload query: data must be a JSON object"}), 400

    db = get_db()
    row = db.execute("SELECT name FROM products WHERE name = ?", (name,)).fetchone()
    if row is None:
        return jsonify({"error": "Product not found"}), 400

    db.execute("UPDATE products SET data = ? WHERE name = ?", (data, name))
    db.commit()
    return jsonify({"status": "updated"}), 200


@app.route("/search", methods=["GET"])
def search_products():
    query = request.args.get("query")
    if query is None or query == "":
        return jsonify({"error": "Invalid search query"}), 400

    db = get_db()
    rows = db.execute("SELECT name, data FROM products").fetchall()
    results = []
    q = query.lower()
    for row in rows:
        product = serialize_product(row)
        matched = False
        for v in product.values():
            if isinstance(v, str) and q in v.lower():
                matched = True
                break
        if matched:
            results.append(product)

    return jsonify({"results": results}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
